async function getFlags(tenantId, env, userId) {
  const key = `flags:${tenantId}:${env}`;
  const cached = await redis.hGet(key, userId);
  if (cached) return JSON.parse(cached);

  const flags = await fetchFromAppConfig(tenantId, env);
  const userFlags = evaluateTargeting(flags, userId);
  await redis.hSet(key, userId, JSON.stringify(userFlags), { EX: 60 });
  return userFlags;
}
